import type { Ticket } from './ticket-model';

export interface AssignmentHistory {
  /**
   * @displayName Assignment History
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Assigned To
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  assignedTo: string;
  /**
   * @displayName Assigned By
   * @validationRule Required for create/update operations
   */
  assignedBy: string;
  /**
   * @displayName Assigned Date
   * @validationRule Required for create/update operations
   */
  assignedDate: string;
  /**
   * @displayName Notes
   */
  notes?: string;
  /**
   * @displayName Previous Assignee
   */
  previousAssignee?: string;
  /**
   * @displayName Ticket
   * @validationRule Required for create/update operations
   */
  ticket: Pick<Ticket, 'id' | 'ticketNumber'>;
}

export const _AssignmentHistory = 'AssignmentHistory' as const;